import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"Models and Your Data","description":"","frontmatter":{"title":"Models and Your Data"},"headers":[],"relativePath":"docs/privacy-and-security/trusted-vs-untrusted-models.md","filePath":"docs/privacy-and-security/trusted-vs-untrusted-models.md","lastUpdated":1794188847000}'),s={name:"docs/privacy-and-security/trusted-vs-untrusted-models.md"};function n(d,e,h,c,u,i){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="models-and-your-data" tabindex="-1">Models and Your Data <a class="header-anchor" href="#models-and-your-data" aria-label="Permalink to &quot;Models and Your Data&quot;">​</a></h1><p>The model you chat with reads your project&#39;s data to answer you: your questions, and the statements, transactions and documents it looks up.</p><h2 id="on-your-computer" tabindex="-1">On your computer <a class="header-anchor" href="#on-your-computer" aria-label="Permalink to &quot;On your computer&quot;">​</a></h2><p><strong>OrbySystems Small</strong>, <strong>Medium</strong> and <strong>Large</strong>, and <strong>OrbySystems Embedding</strong>, run on your own computer. What they read never leaves it. While you use one, the sidebar&#39;s <strong>AI Model</strong> card says &quot;On this computer&quot;.</p><h2 id="somewhere-else" tabindex="-1">Somewhere else <a class="header-anchor" href="#somewhere-else" aria-label="Permalink to &quot;Somewhere else&quot;">​</a></h2><p>If you choose a model that runs somewhere else in <a href="/docs/settings/models">Settings → Models</a> (a cloud model, or one on another machine), it receives every message you send and what it reads to answer. Choose one only if you trust where it runs. The <strong>AI Model</strong> card then names the model in amber, and its dialog shows how much of each chat and project has been sent to it.</p><h2 id="what-else-can-reach-the-network" tabindex="-1">What else can reach the network <a class="header-anchor" href="#what-else-can-reach-the-network" aria-label="Permalink to &quot;What else can reach the network&quot;">​</a></h2><p>Tools such as web search and the browser, and scripts the model writes, are covered by the sidebar&#39;s <strong>Network</strong> card. See <a href="/docs/privacy-and-security/private-data">Private data</a>.</p>',8)])])}const p=t(s,[["render",n]]);export{m as __pageData,p as default};
